(106, 'widget_block', 'a:16:{i:2;a:1:{s:7:\"content\";s:19:\"<!-- wp:search /-->\";}i:3;a:1:{s:7:\"content\";s:154:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h2>Recent Posts</h2><!-- /wp:heading --><!-- wp:latest-posts /--></div><!-- /wp:group -->\";}i:4;a:1:{s:7:\"content\";s:227:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h2>Recent Comments</h2><!-- /wp:heading --><!-- wp:latest-comments {\"displayAvatar\":false,\"displayDate\":false,\"displayExcerpt\":false} /--></div><!-- /wp:group -->\";}i:5;a:1:{s:7:\"content\";s:146:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h2>Archives</h2><!-- /wp:heading --><!-- wp:archives /--></div><!-- /wp:group -->\";}i:6;a:1:{s:7:\"content\";s:150:\"<!-- wp:group --><div class=\"wp-block-group\"><!-- wp:heading --><h2>Categories</h2><!-- /wp:heading --><!-- wp:categories /--></div><!-- /wp:group -->\";}i:1;a:1:{s:7:\"content\";s:1329:\"<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"level\":3,\"style\":{\"typography\":{\"fontSize\":\"18px\"}}} -->\n<h3 class=\"wp-block-heading\" style=\"font-size:18px\">Posts</h3>\n<!-- /wp:heading -->\n\n<!-- wp:blocksy/query {\"uniqueId\":\"c222456c\"} -->\n<div class=\"wp-block-blocksy-query\"><!-- wp:blocksy/post-template {\"layout\":{\"type\":\"default\",\"columnCount\":3}} -->\n<!-- wp:columns {\"style\":{\"spacing\":{\"blockGap\":{\"left\":\"20px\"}}}} -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"25%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:25%\"><!-- wp:blocksy/dynamic-data {\"field\":\"wp:featured_image\",\"aspectRatio\":\"1\",\"sizeSlug\":\"thumbnail\",\"has_field_link\":\"yes\"} /--></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"75%\"} -->\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:75%\"><!-- wp:blocksy/dynamic-data {\"tagName\":\"h2\",\"has_field_link\":\"yes\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"var:preset|spacing|20\"}},\"typography\":{\"fontSize\":\"15px\",\"fontWeight\":\"500\"}}} /-->\n\n<!-- wp:blocksy/dynamic-data {\"field\":\"wp:date\",\"style\":{\"typography\":{\"fontSize\":\"13px\"}}} /--></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n<!-- /wp:blocksy/post-template --></div>\n<!-- /wp:blocksy/query --></div>\n<!-- /wp:group -->\";}i:7;a:1:{s:7:\"content\";s:1433:\"<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|60\",\"right\":\"var:preset|spacing|60\",\"bottom\":\"var:preset|spacing|60\",\"left\":\"var:preset|spacing|60\"}}},\"backgroundColor\":\"palette-color-4\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-palette-color-4-background-color has-background\" style=\"padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--60)\"><!-- wp:heading {\"level\":4,\"textColor\":\"palette-color-8\"} -->\n<h4 class=\"wp-block-heading has-palette-color-8-color has-text-color\">Apply Now - 30% Off</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"textColor\":\"palette-color-6\"} -->\n<p class=\"has-palette-color-6-color has-text-color\">Hurry up! Offer ending soon!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"textColor\":\"palette-color-6\"} -->\n<p class=\"has-palette-color-6-color has-text-color\">Etortor at risus viverra adipiscing at in tellus integer. Ultrices dui sapien eget mi proin sed libero accumsan lacus vel facilisis.<br><br>Sem fringilla ut morbi tincidunt augue interdum velit euismod.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class=\"wp-block-buttons\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\">Apply Now</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\";}i:8;a:1:{s:7:\"content\";s:346:\"<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><a href=\"/gioi-thieu\">Giới thiệu</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"/lien-he\">Liên hệ</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"/ltuyen-dung\">Tuyển dụng</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";}i:9;a:1:{s:7:\"content\";s:272:\"<!-- wp:image {\"id\":30,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"https://wordpress-566072-2146620.cloudwaysapps.com/wp-content/uploads/2021/09/logo-light.svg\" alt=\"\" class=\"wp-image-30\"/></figure>\n<!-- /wp:image -->\";}i:10;a:1:{s:7:\"content\";s:331:\"<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"left\"}}} -->\n<p class=\"has-text-align-left\">Dịch vụ lái xe hộ 24/7, an toàn – nhanh chóng – chuyên nghiệp. Đội ngũ tài xế kinh nghiệm, phục vụ tận nơi, hỗ trợ khách hàng về nhà an toàn mọi lúc mọi nơi.</p>\n<!-- /wp:paragraph -->\";}i:11;a:1:{s:7:\"content\";s:614:\"<!-- wp:blocksy/widgets-wrapper {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|50\"}}}} -->\n<!-- wp:blocksy/socials {\"socials\":[{\"id\":\"facebook\",\"enabled\":true},{\"id\":\"twitter\",\"enabled\":true},{\"id\":\"instagram\",\"enabled\":true},{\"id\":\"youtube\",\"enabled\":true,\"__id\":\"SaUfvlgFbU4WkOcbH-rSz\"}],\"social_type\":\"rounded\",\"social_icons_fill\":\"solid\",\"initialColor\":\"palette-color-1\",\"hoverColor\":\"palette-color-2\",\"customBackgroundColor\":\"#ffffff1a\",\"customBackgroundHoverColor\":\"#ffffff30\",\"lock\":{\"remove\":true}} -->\n<div>Blocksy: Socials</div>\n<!-- /wp:blocksy/socials -->\n<!-- /wp:blocksy/widgets-wrapper -->\";}i:12;a:1:{s:7:\"content\";s:315:\"<!-- wp:list -->\n<ul class=\"wp-block-list\"><!-- wp:list-item -->\n<li><a href=\"#\">Pricing Plans</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"#\">Download</a></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><a href=\"#\">Privacy Policy</a></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\";}s:12:\"_multiwidget\";i:1;i:14;a:1:{s:7:\"content\";s:227:\"<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\";}i:15;a:1:{s:7:\"content\";s:91:\"<!-- wp:code -->\n<pre class=\"wp-block-code\"><code>&lt;p>Helo</code></pre>\n<!-- /wp:code -->\";}i:16;a:1:{s:7:\"content\";s:1320:\"<div class=\"social-wrapper\">\n\n    <div class=\"social-title\">Theo dõi chúng tôi tại</div>\n\n    <div class=\"social-group\">\n\n        <a class=\"social-item facebook\" href=\"https://facebook.com\" target=\"_blank\">\n            <svg viewBox=\"0 0 24 24\" fill=\"currentColor\">\n                <path d=\"M22 12a10 10 0 1 0-11.5 9.9v-7H8v-3h2.5V9.8c0-2.5 1.5-3.9 3.8-3.9 1.1 0 2.2.2 2.2.2v2.4H15.2c-1.2 0-1.6.7-1.6 1.5V12H18l-.5 3h-2.9v7A10 10 0 0 0 22 12z\"/>\n            </svg>\n        </a>\n\n        <a class=\"social-item youtube\" href=\"https://youtube.com\" target=\"_blank\">\n            <svg viewBox=\"0 0 24 24\" fill=\"currentColor\">\n                <path d=\"M23 12s0-3.6-.5-5.3c-.3-1-1-1.7-2-2C18.8 4.2 12 4.2 12 4.2s-6.8 0-8.5.5c-1 .3-1.7 1-2 2C1 8.4 1 12 1 12s0 3.6.5 5.3c.3 1 1 1.7 2 2 1.7.5 8.5.5 8.5.5s6.8 0 8.5-.5c1-.3 1.7-1 2-2 .5-1.7.5-5.3.5-5.3z\"/>\n                <path d=\"M10 15.5v-7l6 3.5-6 3.5z\"/>\n            </svg>\n        </a>\n\n        <a class=\"social-item tiktok\" href=\"https://tiktok.com\" target=\"_blank\">\n            <svg viewBox=\"0 0 24 24\" fill=\"currentColor\">\n                <path d=\"M16 3c.3 2.6 1.9 4.6 4 5v3c-1.7 0-3.3-.5-4.7-1.4V15c0 3.3-2.7 6-6 6s-6-2.7-6-6 2.7-6 6-6c.3 0 .7 0 1 .1v3.1c-.3-.1-.6-.2-1-.2-1.7 0-3 1.3-3 3s1.3 3 3 3 3-1.3 3-3V3h3z\"/>\n            </svg>\n        </a>\n\n    </div>\n\n</div>\";}}'