(879, 1, '2026-06-01 10:13:15', '2026-06-01 10:13:15', '{\n    \"custom_css[blocksy]\": {\n        \"value\": \"/* Modula Gallery */\\n.modula-item-content:hover img {\\n\\ttransform: scale(1.1);\\n}\\n\\n@media (max-width: 1024px) {\\n.ct-testimonial .elementor-image-box-wrapper {\\n  flex-wrap: wrap;\\n}\\n.ct-testimonial .elementor-image-box-wrapper .elementor-image-box-img {\\n  margin-bottom: 10px !important;\\n}\\n}\\n\\n.hero-section {\\n\\tbackground: radial-gradient(70% 50% at 20% 30%, #00c4a02e, #0000 60%), radial-gradient(60% 60% at 80% 20%, #4f6ef724, #0000 55%), radial-gradient(50% 40% at 60% 80%, #00cfee21, #0000 50%), #fafbff;\\n}\\n\\n#main {\\n\\tbackground-color: #FAFBFF;\\n}\\n\\n.section_home {\\n\\tmargin-top: 64px;\\n}\\n.gradient-text {\\n\\t-webkit-text-fill-color: transparent;\\n    color: #0000;\\n    background: linear-gradient(135deg, #00c4a0, #00cfee, #4f6ef7);\\n    -webkit-background-clip: text;\\n    background-clip: text;\\n\\t-webkit-text-fill-color: transparent;\\n}\\n\\n.grad-cta {\\n    color: #fff;\\n    background: linear-gradient(135deg, #00c4a0, #00cfee)!important;\\n    transition: all .2s;\\n    box-shadow: 0 2px 14px #00c4a059, inset 0 1px #ffffff40 !important;\\n}\\n\\n.grad-cta:hover {\\n    filter: brightness(1.05);\\n    box-shadow: 0 8px 32px #00c4a073;\\n}\\n\\n.price-table {\\n    width: 100%;\\n    border-collapse: separate;\\n    border-spacing: 0;\\n\\n    border: 1px solid #e5e7eb;\\n    border-radius: 24px;\\n    overflow: hidden;\\n\\n    background: #fff;\\n    font-family: Inter, sans-serif;\\n}\\n\\n.price-table th,\\n.price-table td {\\n    padding: 18px 24px;\\n    border-bottom: 1px solid #e5e7eb;\\n}\\n\\n.price-table tbody tr:last-child td,\\n.price-table tfoot td {\\n    border-bottom: none;\\n}\\n\\n.price-table th {\\n    background: #f3f4f8;\\n    color: #344054;\\n    font-size: 14px;\\n    font-weight: 700;\\n    text-transform: uppercase;\\n    letter-spacing: .03em;\\n}\\n\\n.price-table td {\\n    color: #475467;\\n    font-size: 15px;\\n}\\n\\n/* C\\u0103n gi\\u1eefa gi\\u00e1 */\\n.price-table td:nth-child(2),\\n.price-table td:nth-child(3),\\n.price-table th:nth-child(2),\\n.price-table th:nth-child(3) {\\n    text-align: center;\\n}\\n\\n/* C\\u1ed9t kho\\u1ea3ng c\\u00e1ch */\\n.price-table td:first-child {\\n    font-weight: 600;\\n    color: #101828;\\n}\\n\\n/* Gi\\u00e1 ban ng\\u00e0y */\\n.price-table td:nth-child(2) {\\n    color: #0f766e;\\n    font-weight: 600;\\n}\\n\\n/* Gi\\u00e1 ban \\u0111\\u00eam */\\n.price-table td:nth-child(3) {\\n    color: #2563eb;\\n    font-weight: 600;\\n}\\n\\n/* Hover */\\n.price-table tbody tr:hover {\\n    background: #f8fafc;\\n}\\n\\n/* D\\u00f2ng cu\\u1ed1i */\\n.price-table tfoot td {\\n    background: #f9fafb;\\n    font-weight: 700;\\n    color: #111827;\\n}\\n\\n.section-title .title {\\n\\tfont-weight: 800;\\n\\ttext-align: center;\\n}\\n.section-title .sub-title {\\n\\tfont-size: 11px;\\n\\tfont-weight: 700;\\n\\tcolor: #00c4a0;\\n\\tline-height: 17px;\\n\\ttext-align: center;\\n\\tmargin-block-end: 0px;\\n}\\n\\n.card-box > .card {\\n\\tborder-radius: 32px;\\n\\tborder: 1px solid #F3F5F9;\\n\\tbackground-color: #FFFFFF;\\n}\\n\\n.card-hover-able:hover {\\n    border-color: #00c4a073;\\n    transform: translateY(-3px);\\n    box-shadow: 0 12px 32px #00c4a01f;\\n}\\n\\n.solution-section .e-svg-base {\\n\\tbackground-color: #DCF7FD;\\n\\tcolor: #4D658A;\\n\\tborder-radius: 50%;\\n  padding: 8px;\\n}\\n\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-06-01 10:13:15\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'abd62b91-ebbf-4b21-aa17-91d19e5bb70e', '', '', '2026-06-01 10:13:15', '2026-06-01 10:13:15', '', 0, 'http://laixeho.test/2026/06/01/abd62b91-ebbf-4b21-aa17-91d19e5bb70e/', 0, 'customize_changeset', '', 0),
(880, 1, '2026-06-01 10:13:15', '2026-06-01 10:13:15', '/* Modula Gallery */\n.modula-item-content:hover img {\n	transform: scale(1.1);\n}\n\n@media (max-width: 1024px) {\n.ct-testimonial .elementor-image-box-wrapper {\n  flex-wrap: wrap;\n}\n.ct-testimonial .elementor-image-box-wrapper .elementor-image-box-img {\n  margin-bottom: 10px !important;\n}\n}\n\n.hero-section {\n	background: radial-gradient(70% 50% at 20% 30%, #00c4a02e, #0000 60%), radial-gradient(60% 60% at 80% 20%, #4f6ef724, #0000 55%), radial-gradient(50% 40% at 60% 80%, #00cfee21, #0000 50%), #fafbff;\n}\n\n#main {\n	background-color: #FAFBFF;\n}\n\n.section_home {\n	margin-top: 64px;\n}\n.gradient-text {\n	-webkit-text-fill-color: transparent;\n    color: #0000;\n    background: linear-gradient(135deg, #00c4a0, #00cfee, #4f6ef7);\n    -webkit-background-clip: text;\n    background-clip: text;\n	-webkit-text-fill-color: transparent;\n}\n\n.grad-cta {\n    color: #fff;\n    background: linear-gradient(135deg, #00c4a0, #00cfee)!important;\n    transition: all .2s;\n    box-shadow: 0 2px 14px #00c4a059, inset 0 1px #ffffff40 !important;\n}\n\n.grad-cta:hover {\n    filter: brightness(1.05);\n    box-shadow: 0 8px 32px #00c4a073;\n}\n\n.price-table {\n    width: 100%;\n    border-collapse: separate;\n    border-spacing: 0;\n\n    border: 1px solid #e5e7eb;\n    border-radius: 24px;\n    overflow: hidden;\n\n    background: #fff;\n    font-family: Inter, sans-serif;\n}\n\n.price-table th,\n.price-table td {\n    padding: 18px 24px;\n    border-bottom: 1px solid #e5e7eb;\n}\n\n.price-table tbody tr:last-child td,\n.price-table tfoot td {\n    border-bottom: none;\n}\n\n.price-table th {\n    background: #f3f4f8;\n    color: #344054;\n    font-size: 14px;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: .03em;\n}\n\n.price-table td {\n    color: #475467;\n    font-size: 15px;\n}\n\n/* Căn giữa giá */\n.price-table td:nth-child(2),\n.price-table td:nth-child(3),\n.price-table th:nth-child(2),\n.price-table th:nth-child(3) {\n    text-align: center;\n}\n\n/* Cột khoảng cách */\n.price-table td:first-child {\n    font-weight: 600;\n    color: #101828;\n}\n\n/* Giá ban ngày */\n.price-table td:nth-child(2) {\n    color: #0f766e;\n    font-weight: 600;\n}\n\n/* Giá ban đêm */\n.price-table td:nth-child(3) {\n    color: #2563eb;\n    font-weight: 600;\n}\n\n/* Hover */\n.price-table tbody tr:hover {\n    background: #f8fafc;\n}\n\n/* Dòng cuối */\n.price-table tfoot td {\n    background: #f9fafb;\n    font-weight: 700;\n    color: #111827;\n}\n\n.section-title .title {\n	font-weight: 800;\n	text-align: center;\n}\n.section-title .sub-title {\n	font-size: 11px;\n	font-weight: 700;\n	color: #00c4a0;\n	line-height: 17px;\n	text-align: center;\n	margin-block-end: 0px;\n}\n\n.card-box > .card {\n	border-radius: 32px;\n	border: 1px solid #F3F5F9;\n	background-color: #FFFFFF;\n}\n\n.card-hover-able:hover {\n    border-color: #00c4a073;\n    transform: translateY(-3px);\n    box-shadow: 0 12px 32px #00c4a01f;\n}\n\n.solution-section .e-svg-base {\n	background-color: #DCF7FD;\n	color: #4D658A;\n	border-radius: 50%;\n  padding: 8px;\n}\n', 'blocksy', '', 'inherit', 'closed', 'closed', '', '37-revision-v1', '', '', '2026-06-01 10:13:15', '2026-06-01 10:13:15', '', 37, 'http://laixeho.test/?p=880', 0, 'revision', '', 0),
(881, 1, '2026-06-01 10:18:17', '2026-06-01 10:18:17', '<p data-interaction-id=\"a799394\">Dịch vụ</p>\n					<h1 data-interaction-id=\"85f6b14\">Lái Xe Hộ Người Uống Rượu Bia</h1>\n										<a href=\"http://zalo.me/0387597099\">\n									Đặt qua Zalo\n					</a>\n						<p>Giải pháp</p>\n<h2>Đã uống rượu bia thì \nthuê lái xe</h2>			<svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"currentColor\" style=\"width: 100%; height: 100%; overflow: unset;\" width=\"512\" height=\"512\" viewbox=\"0 0 24 24\"><path fill=\"#000000\" d=\"M19.99 3.753a.5.5 0 0 0-.593-.387a9.106 9.106 0 0 1-7.11-1.454a.5.5 0 0 0-.574 0a9.107 9.107 0 0 1-7.11 1.454a.498.498 0 0 0-.603.49v8.018a9.131 9.131 0 0 0 3.799 7.407l3.91 2.804a.497.497 0 0 0 .582 0l3.91-2.804A9.131 9.131 0 0 0 20 11.874V3.855a.498.498 0 0 0-.01-.102zM19 11.874a8.129 8.129 0 0 1-3.38 6.595L12 21.063L8.38 18.47A8.13 8.13 0 0 1 5 11.874v-7.42a10.082 10.082 0 0 0 7-1.53a10.085 10.085 0 0 0 7 1.53v7.42z\"></path></svg>					<h5 data-interaction-id=\"bd4a4d6\"><strong id=\"e-mpuworms-s78y7ig\">An toàn cho bạn và cộng đồng</strong></h5>\n					<p data-interaction-id=\"a7fd6ce\">Uống rượu bia lái xe là một tội ác gây ảnh hưởng cho tài xế và cộng đồng. Dịch vụ lái xe hộ giúp bảo vệ bạn và mọi người an toàn khi tham gia giao thông.</p>\n					<svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"currentColor\" style=\"width: 100%; height: 100%; overflow: unset;\" width=\"512\" height=\"512\" viewbox=\"0 0 24 24\"><path fill=\"#000000\" d=\"M19.99 3.753a.5.5 0 0 0-.593-.387a9.106 9.106 0 0 1-7.11-1.454a.5.5 0 0 0-.574 0a9.107 9.107 0 0 1-7.11 1.454a.498.498 0 0 0-.603.49v8.018a9.131 9.131 0 0 0 3.799 7.407l3.91 2.804a.497.497 0 0 0 .582 0l3.91-2.804A9.131 9.131 0 0 0 20 11.874V3.855a.498.498 0 0 0-.01-.102zM19 11.874a8.129 8.129 0 0 1-3.38 6.595L12 21.063L8.38 18.47A8.13 8.13 0 0 1 5 11.874v-7.42a10.082 10.082 0 0 0 7-1.53a10.085 10.085 0 0 0 7 1.53v7.42z\"></path></svg>					<h5 data-interaction-id=\"a832228\"><strong>Tài xế kinh nghiệm</strong></h5>\n					<p data-interaction-id=\"48aee90\">Tài xế kinh nghiệm lái xe trên 5 năm. Thái độ nhiệt tình, chu đáo và minh bạch trong quá trình phục vụ sẽ mang lại sự yên tâm và hài lòng tuyệt đối cho bạn.</p>\n					<svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"currentColor\" style=\"width: 100%; height: 100%; overflow: unset;\" width=\"512\" height=\"512\" viewbox=\"0 0 24 24\"><path fill=\"#000000\" d=\"M19.99 3.753a.5.5 0 0 0-.593-.387a9.106 9.106 0 0 1-7.11-1.454a.5.5 0 0 0-.574 0a9.107 9.107 0 0 1-7.11 1.454a.498.498 0 0 0-.603.49v8.018a9.131 9.131 0 0 0 3.799 7.407l3.91 2.804a.497.497 0 0 0 .582 0l3.91-2.804A9.131 9.131 0 0 0 20 11.874V3.855a.498.498 0 0 0-.01-.102zM19 11.874a8.129 8.129 0 0 1-3.38 6.595L12 21.063L8.38 18.47A8.13 8.13 0 0 1 5 11.874v-7.42a10.082 10.082 0 0 0 7-1.53a10.085 10.085 0 0 0 7 1.53v7.42z\"></path></svg>					<h5 data-interaction-id=\"b2a996b\"><strong>Chi phí thanh toán</strong><br></h5>\n					<p data-interaction-id=\"8d41883\">Chi phí sẽ báo trước khi bạn đồng ý đặt tài xế lái xe hộ. Bạn sẽ không phải trả bất cứ thêm mọi khoản phụ phí nào trong quá trình sử dụng dịch vụ.</p>\n		<p>Bảng giá</p>\n<h2>Giá cả\ncạnh tranh, minh bạch</h2><table>\n    <thead>\n        <tr>\n            <th>Khoảng cách</th>\n            <th>Trước 22h (06h-22h)</th>\n            <th>Sau 22h (22h-06h)</th>\n        </tr>\n    </thead>\n    <tbody>\n        <tr><td>&lt; 5 km</td><td>250.000</td><td>280.000</td></tr>\n        <tr><td>6 km</td><td>265.000</td><td>295.000</td></tr>\n        <tr><td>7 km</td><td>280.000</td><td>310.000</td></tr>\n        <tr><td>8 km</td><td>295.000</td><td>325.000</td></tr>\n        <tr><td>9 km</td><td>310.000</td><td>335.000</td></tr>\n        <tr><td>10 km</td><td>320.000</td><td>350.000</td></tr>\n        <tr><td>11 km</td><td>330.000</td><td>365.000</td></tr>\n        <tr><td>12 km</td><td>345.000</td><td>380.000</td></tr>\n        <tr><td>13 km</td><td>360.000</td><td>395.000</td></tr>\n        <tr><td>14 km</td><td>370.000</td><td>410.000</td></tr>\n        <tr><td>15 km</td><td>380.000</td><td>420.000</td></tr>\n    </tbody>\n    <tfoot>\n        <tr>\n            <td>Từ 16 km trở lên</td>\n            <td>380.000 + 10.000/km</td>\n            <td>420.000 + 15.000/km</td>\n        </tr>\n    </tfoot>\n</table>', 'Home', '', 'inherit', 'closed', 'closed', '', '704-revision-v1', '', '', '2026-06-01 10:18:17', '2026-06-01 10:18:17', '', 704, 'http://laixeho.test/?p=881', 0, 'revision', '', 0),
