INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1018, 1, '2026-06-01 14:44:16', '2026-06-01 14:44:16', '/* Modula Gallery */\n.modula-item-content:hover img {\n	transform: scale(1.1);\n}\n\n@media (max-width: 1024px) {\n.ct-testimonial .elementor-image-box-wrapper {\n  flex-wrap: wrap;\n}\n.ct-testimonial .elementor-image-box-wrapper .elementor-image-box-img {\n  margin-bottom: 10px !important;\n}\n}\n\n.ct-sticky-container * {\n	max-height: 84px;\n}\n\n.hero-section {\n	background: radial-gradient(70% 50% at 20% 30%, #00c4a02e, #0000 60%), radial-gradient(60% 60% at 80% 20%, #4f6ef724, #0000 55%), radial-gradient(50% 40% at 60% 80%, #00cfee21, #0000 50%), #fafbff;\n}\n\n.hero-section div {\n	padding: 0;\n}\n\n#main {\n	background-color: #FAFBFF;\n}\n\n.section_home {\n	margin-top: 64px;\n}\n.gradient-text {\n	-webkit-text-fill-color: transparent;\n    color: #0000;\n    background: linear-gradient(135deg, #00c4a0, #00cfee, #4f6ef7);\n    -webkit-background-clip: text;\n    background-clip: text;\n	-webkit-text-fill-color: transparent;\n}\n\n.hero-section .hero-title {\n	text-align: center;\n}\n.hero-section .cta-group-btn {\n	margin-top: 32px;\n}\n\n.grad-cta {\n    color: #fff;\n    background: linear-gradient(135deg, #00c4a0, #00cfee)!important;\n    transition: all .2s;\n    box-shadow: 0 2px 14px #00c4a059, inset 0 1px #ffffff40 !important;\n}\n\n.grad-cta:hover {\n    filter: brightness(1.05);\n		color: #FFFFFF;\n    box-shadow: 0 8px 32px #00c4a073 !important;\n}\n\n.hero-cta {\n	font-weight: 600;\n	font-size: 14px;\n	line-height: 20px;\n	border: 1px solid #0b235614;\n  border-radius: 9999px;\n  padding: 14px 24px;\n}\n\n.primary-cta {\n	color: #FFFFFF;\n	border: 1px solid #0b235614;\n}\n\n.secondary-cta {\n	color: #080e1f;\n	border: 1px solid #0b235614;\n}\n.secondary-cta:hover {\n	color:  #080e1f;\n	border-color: color-mix(in oklab, #080e1f 20%,transparent);\n}\n\n.hero-section .sub-title-1 {\n	display: inline-flex;\n	background-color: #FFFFFF;\n	color: #D5D7DC;\n	border: 1px solid #0b235614;\n	max-width: max-content;\n	border-radius: 9999px;\n	padding: 6px 12px;\n	box-shadow:\n    0 1px 2px rgba(0, 0, 0, 0.04),\n    0 3px 6px rgba(0, 0, 0, 0.05),\n    0 6px 12px rgba(0, 0, 0, 0.06);\n}\n\n.hero-section .sub-title-1 h6 {\n	font-weight: 600;\n	font-size: 12px;\n	line-height: 16px;\n}\n\n.sub-title-1 .e-svg-base {\n	width: 20px;\n	height: 20px;\n	background-color: #00C8BB;\n	color: #FFFFFF;\n	border-radius: 50%;\n	path {\n    fill: currentColor;\n	}\n}\n\n.price-table {\n    width: 100%;\n    border-collapse: separate;\n    border-spacing: 0;\n\n    border: 1px solid #e5e7eb;\n    border-radius: 24px;\n    overflow: hidden;\n\n    background: #fff;\n    font-family: Inter, sans-serif;\n}\n\n.price-table th,\n.price-table td {\n    padding: 18px 24px;\n    border-bottom: 1px solid #e5e7eb;\n}\n\n.price-table tbody tr:last-child td,\n.price-table tfoot td {\n    border-bottom: none;\n}\n\n.price-table th {\n    background: #f3f4f8;\n    color: #344054;\n    font-size: 14px;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: .03em;\n}\n\n.price-table td {\n    color: #475467;\n    font-size: 15px;\n}\n\n/* Căn giữa giá */\n.price-table td:nth-child(2),\n.price-table td:nth-child(3),\n.price-table th:nth-child(2),\n.price-table th:nth-child(3) {\n    text-align: center;\n}\n\n/* Cột khoảng cách */\n.price-table td:first-child {\n    font-weight: 600;\n    color: #101828;\n}\n\n/* Giá ban ngày */\n.price-table td:nth-child(2) {\n    color: #0f766e;\n    font-weight: 600;\n}\n\n/* Giá ban đêm */\n.price-table td:nth-child(3) {\n    color: #2563eb;\n    font-weight: 600;\n}\n\n/* Hover */\n.price-table tbody tr:hover {\n    background: #f8fafc;\n}\n\n/* Dòng cuối */\n.price-table tfoot td {\n    background: #f9fafb;\n    font-weight: 700;\n    color: #111827;\n}\n\n.section-title .title {\n	font-weight: 800;\n	text-align: center;\n}\n.section-title .sub-title {\n	font-size: 11px;\n	font-weight: 700;\n	color: #00c4a0;\n	line-height: 17px;\n	text-align: center;\n	margin-block-end: 0px;\n}\n\n.card-box > .card {\n	border-radius: 32px;\n	border: 1px solid #F3F5F9;\n	background-color: #FFFFFF;\n}\n\n.card-hover-able:hover {\n    border-color: #00c4a073;\n    transform: translateY(-3px);\n    box-shadow: 0 12px 32px #00c4a01f;\n}\n\n.solution-section .e-svg-base {\n	background-color: #DCF7FD;\n	color: #4D658A;\n	border-radius: 50%;\n  padding: 8px;\n}\n', 'blocksy', '', 'inherit', 'closed', 'closed', '', '37-revision-v1', '', '', '2026-06-01 14:44:16', '2026-06-01 14:44:16', '', 37, 'http://laixeho.test/?p=1018', 0, 'revision', '', 0),
