h: max-content;\n	border-radius: 9999px;\n	padding: 6px 12px;\n	box-shadow:\n    0 1px 2px rgba(0, 0, 0, 0.04),\n    0 3px 6px rgba(0, 0, 0, 0.05),\n    0 6px 12px rgba(0, 0, 0, 0.06);\n}\n\n.hero-section .sub-title-1 h6 {\n	font-weight: 600;\n	font-size: 12px;\n	line-height: 16px;\n}\n\n.sub-title-1 .e-svg-base {\n	width: 20px;\n	height: 20px;\n	background-color: #00C8BB;\n	color: #FFFFFF;\n	border-radius: 50%;\n	path {\n    fill: currentColor;\n	}\n}\n\n.price-table {\n    width: 100%;\n    border-collapse: collapse;\n    background: #fff;\n    border: 1px solid #e5e7eb;           /* Border ngoài cùng */\n    border-radius: 24px;\n    overflow: hidden;\n    font-family: Inter, sans-serif;\n}\n\n/* Tất cả ô đều có border ngang */\n.price-table th,\n.price-table td {\n    padding: 18px 24px;\n    border-bottom: 1px solid #e5e7eb;\n}\n\n/* Header */\n.price-table th {\n    background: #f3f4f8;\n    color: #344054;\n    font-size: 14px;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: .03em;\n    text-align: left;\n}\n\n/* Body */\n.price-table tbody td {\n    color: #475467;\n    font-size: 15px;\n}\n\n/* Bỏ border dòng cuối body */\n.price-table tbody tr:last-child td {\n    border-bottom: none;\n}\n\n/* Footer */\n.price-table tfoot td {\n    background: #f9fafb;\n    color: #111827;\n    font-weight: 700;\n    border-top: 1px solid #e5e7eb;\n}\n\n/* Các style còn lại giữ nguyên */\n.price-table th:nth-child(2),\n.price-table th:nth-child(3),\n.price-table td:nth-child(2),\n.price-table td:nth-child(3) {\n    text-align: center;\n}\n\n.price-table td:first-child {\n    font-weight: 600;\n    color: #101828;\n}\n\n.price-table td:nth-child(2) { color: #0f766e; font-weight: 600; }\n.price-table td:nth-child(3) { color: #2563eb; font-weight: 600; }\n\n.price-table tbody tr:hover {\n    background: #f8fafc;\n}\n\n.section-title .title {\n	font-weight: 800;\n	text-align: center;\n}\n.section-title .sub-title {\n	font-size: 11px;\n	font-weight: 700;\n	color: #00c4a0;\n	line-height: 17px;\n	text-align: center;\n	margin-block-end: 0px;\n}\n\n.card-box > .card {\n	border-radius: 32px;\n	border: 1px solid #F3F5F9;\n	background-color: #FFFFFF;\n}\n\n.card-hover-able:hover {\n    border-color: #00c4a073;\n    transform: translateY(-3px);\n    box-shadow: 0 12px 32px #00c4a01f;\n}\n\n.solution-section .e-svg-base {\n	background-color: #DCF7FD;\n	color: #4D658A;\n	border-radius: 50%;\n  padding: 8px;\n}\n', 'blocksy', '', 'inherit', 'closed', 'closed', '', '37-revision-v1', '', '', '2026-06-01 15:05:24', '2026-06-01 15:05:24', '', 37, 'http://laixeho.test/?p=1024', 0, 'revision', '', 0),
