h: max-content;\n	border-radius: 9999px;\n	padding: 6px 12px;\n	box-shadow:\n    0 1px 2px rgba(0, 0, 0, 0.04),\n    0 3px 6px rgba(0, 0, 0, 0.05),\n    0 6px 12px rgba(0, 0, 0, 0.06);\n}\n\n.hero-section .sub-title-1 h6 {\n	font-weight: 600;\n	font-size: 12px;\n	line-height: 16px;\n}\n\n.sub-title-1 .e-svg-base {\n	width: 20px;\n	height: 20px;\n	background-color: #00C8BB;\n	color: #FFFFFF;\n	border-radius: 50%;\n	path {\n    fill: currentColor;\n	}\n}\n\n.price-grid {\n    display: grid;\n    grid-template-columns: 1.2fr 1fr 1fr;\n\n    gap: 1px;\n    padding: 1px;\n\n    background: #F3F5F9;\n    border-radius: 24px;\n    overflow: hidden;\n\n    box-shadow:\n        0 1px 2px rgba(16, 24, 40, .03),\n        0 8px 24px rgba(16, 24, 40, .04);\n}\n\n.cell {\n    background: #fff;\n    padding: 18px 24px;\n\n    color: #475467;\n    font-size: 15px;\n    transition: background-color .2s ease;\n}\n\n.head {\n    background: #F8FAFC;\n\n    color: #344054;\n    font-size: 14px;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: .03em;\n}\n\n.distance {\n    font-weight: 600;\n    color: #101828;\n}\n\n.day {\n    text-align: center;\n    color: #0F766E;\n    font-weight: 600;\n}\n\n.night {\n    text-align: center;\n    color: #2563EB;\n    font-weight: 600;\n}\n\n.footer {\n    background: #FAFBFC;\n    font-weight: 700;\n    color: #111827;\n}\n\n.price-grid .cell:not(.head):hover {\n    background: #FAFBFC;\n}\n\n.section-title .title {\n	font-weight: 800;\n	text-align: center;\n}\n.section-title .sub-title {\n	font-size: 11px;\n	font-weight: 700;\n	color: #00c4a0;\n	line-height: 17px;\n	text-align: center;\n	margin-block-end: 0px;\n}\n\n.card-box > .card {\n	border-radius: 32px;\n	border: 1px solid #F3F5F9;\n	background-color: #FFFFFF;\n}\n\n.card-hover-able:hover {\n    border-color: #00c4a073;\n    transform: translateY(-3px);\n    box-shadow: 0 12px 32px #00c4a01f;\n}\n\n.solution-section .e-svg-base {\n	background-color: #DCF7FD;\n	colo