n oklab, #080e1f 20%,transparent);\\n}\\n\\n.hero-section .sub-title-1 {\\n\\tdisplay: inline-flex;\\n\\tbackground-color: #FFFFFF;\\n\\tcolor: #D5D7DC;\\n\\tborder: 1px solid #0b235614;\\n\\tmax-width: max-content;\\n\\tborder-radius: 9999px;\\n\\tpadding: 6px 12px;\\n\\tbox-shadow:\\n    0 1px 2px rgba(0, 0, 0, 0.04),\\n    0 3px 6px rgba(0, 0, 0, 0.05),\\n    0 6px 12px rgba(0, 0, 0, 0.06);\\n}\\n\\n.hero-section .sub-title-1 h6 {\\n\\tfont-weight: 600;\\n\\tfont-size: 12px;\\n\\tline-height: 16px;\\n}\\n\\n.sub-title-1 .e-svg-base {\\n\\twidth: 20px;\\n\\theight: 20px;\\n\\tbackground-color: #00C8BB;\\n\\tcolor: #FFFFFF;\\n\\tborder-radius: 50%;\\n\\tpath {\\n    fill: currentColor;\\n\\t}\\n}\\n\\n.price-table {\\n    width: 100%;\\n    border-collapse: separate;\\n    border-spacing: 0;\\n\\n    background: #fff;\\n\\n    border: 1px solid #edf1f5;\\n    border-radius: 28px;\\n    overflow: hidden;\\n\\n    font-family: Inter, sans-serif;\\n}\\n\\n/* Header */\\n.price-table thead th {\\n    background: #f3f4fa;\\n\\n    padding: 24px;\\n\\n    text-align: left;\\n    font-size: 14px;\\n    font-weight: 700;\\n    text-transform: uppercase;\\n\\n    color: #344054;\\n\\n    border-bottom: 1px solid #edf1f5;\\n}\\n\\n.compare-table {\\n    width: 100%;\\n\\n    background: #fff;\\n\\n    border: 1px solid #edf1f5;\\n    border-radius: 32px;\\n    overflow: hidden;\\n\\n    font-family: Inter, sans-serif;\\n}\\n\\n.compare-row {\\n    display: grid;\\n    grid-template-columns: 1fr 1fr 1fr;\\n}\\n\\n.compare-row:not(:last-child) {\\n    border-bottom: 1px solid #edf1f5;\\n}\\n\\n.compare-row > div {\\n    padding: 28px 24px;\\n}\\n\\n/* Header */\\n.compare-header {\\n    background: #f4f5fa;\\n}\\n\\n.compare-header > div {\\n    color: #667085;\\n    font-size: 13px;\\n    font-weight: 700;\\n    text-transform: uppercase;\\n    letter-spacing: .04em;\\n}\\n\\n/* C\\u1ed9t 1 */\\n.compare-row:not(.compare-header) > div:nth-child(1) {\\n    color: #101828;\\n    font-size: 16px;\\n    font-weight: 500;\\n}\\n\\n/* C\\u1ed9t 2 */\\n.compare-row:not(.compare-header) > div:nth-child(2) {\\n    color: #667085;\\n    font-size: 16px;\\n}\\n\\n/* C\\u1ed9t 3 */\\n.compare-row:not(.compare-header) > div:nth-child(3) {\\n    color: #00a86b;\\n    font-size: 16px;\\n    font-weight: 600;\\n}\\n\\n/* Hover */\\n.compare-row:not(.compare-header):hover {\\n    background: #fafbfc;\\n    transition: background-color .2s ease;\\n}\\n\\n/* Mobile */\\n@media (max-width: 768px) {\\n    .compare-row {\\n        grid-template-columns: 1fr;\\n    }\\n\\n    .compare-row > div {\\n        padding: 16px 20px;\\n    }\\n\\n    .compare-header {\\n        display: none;\\n    }\\n\\n    .compare-row > div {\\n        border-bottom: 1px solid #edf1f5;\\n    }\\n\\n    .compare-row > div:last-child {\\n        border-bottom: 0;\\n    }\\n}\\n\\n.section-title .title {\\n\\tfont-weight: 800;\\n\\ttext-align: center;\\n}\\n.section-title .sub-title {\\n\\tfont-size: 11px;\\n\\tfont-weight: 700;\\n\\tcolor: #00c4a0;\\n\\tline-height: 17px;\\n\\ttext-align: center;\\n\\tmargin-block-end: 0px;\\n}\\n\\n.card-box > .card {\\n\\tborder-radius: 32px;\\n\\tborder: 1px solid #F3F5F9;\\n\\tbackground-color: #FFFFFF;\\n}\\n\\n.card-hover-able:hover {\\n    border-color: #00c4a073;\\n    transform: translateY(-3px);\\n    box-shadow: 0 12px 32px #00c4a01f;\\n}\\n\\n.solution-section .e-svg-base {\\n\\tbackground-color: #DCF7FD;\\n\\tcolor: #4D658A;\\n\\tborder-radius: 50%;\\n  padding: 8px;\\n}\\n\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-06-01 15:24:36\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '16d1da45-fbc8-4455-8c9a-a9c7b18cf33f', '', '', '2026-06-01 15:24:36', '2026-06-01 15:24:36', '', 0, 'http://laixeho.test/2026/06/01/16d1da45-fbc8-4455-8c9a-a9c7b18cf33f/', 0, 'customize_changeset', '', 0);
