(1043, 1, '2026-06-01 15:30:39', '2026-06-01 15:30:39', '/* Modula Gallery */\n.modula-item-content:hover img {\n	transform: scale(1.1);\n}\n\n@media (max-width: 1024px) {\n.ct-testimonial .elementor-image-box-wrapper {\n  flex-wrap: wrap;\n}\n.ct-testimonial .elementor-image-box-wrapper .elementor-image-box-img {\n  margin-bottom: 10px !important;\n}\n}\n\n.ct-sticky-container * {\n	max-height: 84px;\n}\n\n.hero-section {\n	background: radial-gradient(70% 50% at 20% 30%, #00c4a02e, #0000 60%), radial-gradient(60% 60% at 80% 20%, #4f6ef724, #0000 55%), radial-gradient(50% 40% at 60% 80%, #00cfee21, #0000 50%), #fafbff;\n}\n\n.hero-section div {\n	padding: 0;\n}\n\n#main {\n	background-color: #FAFBFF;\n}\n\n.section_home {\n	margin-top: 64px;\n}\n.gradient-text {\n	-webkit-text-fill-color: transparent;\n    color: #0000;\n    background: linear-gradient(135deg, #00c4a0, #00cfee, #4f6ef7);\n    -webkit-background-clip: text;\n    background-clip: text;\n	-webkit-text-fill-color: transparent;\n}\n\n.hero-section .hero-title {\n	text-align: center;\n}\n.hero-section .cta-group-btn {\n	margin-top: 32px;\n}\n\n.grad-cta {\n    color: #fff;\n    background: linear-gradient(135deg, #00c4a0, #00cfee)!important;\n    transition: all .2s;\n    box-shadow: 0 2px 14px #00c4a059, inset 0 1px #ffffff40 !important;\n}\n\n.grad-cta:hover {\n    filter: brightness(1.05);\n		color: #FFFFFF;\n    box-shadow: 0 8px 32px #00c4a073 !important;\n}\n\n.hero-cta {\n	font-weight: 600;\n	font-size: 14px;\n	line-height: 20px;\n	border: 1px solid #0b235614;\n  border-radius: 9999px;\n  padding: 14px 24px;\n}\n\n.primary-cta {\n	color: #FFFFFF;\n	border: 1px solid #0b235614;\n}\n\n.secondary-cta {\n	color: #080e1f;\n	border: 1px solid #0b235614;\n}\n.secondary-cta:hover {\n	color:  #080e1f;\n	border-color: color-mix(in oklab, #080e1f 20%,transparent);\n}\n\n.hero-section .sub-title-1 {\n	display: inline-flex;\n	background-color: #FFFFFF;\n	color: #D5D7DC;\n	border: 1px solid #0b235614;\n	max-width: max-content;\n	border-radius: 9999px;\n	padding: 6px 12px;\n	box-shadow:\n    0 1px 2px rgba(0, 0, 0, 0.04),\n    0 3px 6px rgba(0, 0, 0, 0.05),\n    0 6px 12px rgba(0, 0, 0, 0.06);\n}\n\n.hero-section .sub-title-1 h6 {\n	font-weight: 600;\n	font-size: 12px;\n	line-height: 16px;\n}\n\n.sub-title-1 .e-svg-base {\n	width: 20px;\n	height: 20px;\n	background-color: #00C8BB;\n	color: #FFFFFF;\n	border-radius: 50%;\n	path {\n    fill: currentColor;\n	}\n}\n\n.price-table {\n    width: 100%;\n    border-collapse: separate;\n    border-spacing: 0;\n\n    background: #fff;\n\n    border: 1px solid #edf1f5;\n    border-radius: 28px;\n    overflow: hidden;\n\n    font-family: Inter, sans-serif;\n}\n\n/* Header */\n.price-table thead th {\n    background: #f3f4fa;\n\n    padding: 24px;\n\n    text-align: left;\n    font-size: 14px;\n    font-weight: 700;\n    text-transform: uppercase;\n\n    color: #344054;\n\n    border-bottom: 1px solid #edf1f5;\n}\n\n.compare-table {\n    width: 100%;\n\n    background: #fff;\n\n   \n    border-radius: 32px;\n    overflow: hidden;\n\n    font-family: Inter, sans-serif;\n}\n\n.compare-row {\n    display: grid;\n    grid-template-columns: 1fr 1fr 1fr;\n}\n\n.compare-row:not(:last-child) {\n    border-bottom: 1px solid #edf1f5;\n}\n\n.compare-row > div {\n    padding: 28px 24px;\n}\n\n/* Header */\n.compare-header {\n    background: #F4F6FF;\n}\n\n.compare-header > div {\n    color: #667085;\n    font-size: 13px;\n    font-weight: 700;\n    text-transform: uppercase;\n    letter-spacing: .04em;\n}\n\n/* Cột 1 */\n.compare-row:not(.compare-header) > div:nth-child(1) {\n    color: #101828;\n    font-size: 16px;\n    font-weight: 500;\n}\n\n/* Cột 2 */\n.compare-row:not(.compare-header) > div:nth-child(2) {\n    color: #667085;\n    font-size: 16px;\n}\n\n/* Cột 3 */\n.compare-row:not(.compare-header) > div:nth-child(3) {\n    color: #00a86b;\n    font-size: 16px;\n    font-weight: 600;\n}\n\n/* Hover */\n.compare-row:not(.compare-header):hover {\n    background: #fafbfc;\n    transition: background-color .2s ease;\n}\n\n/* Mobile */\n@media (max-width: 768px) {\n    .compare-row {\n        grid-template-columns: 1fr;\n    }\n\n    .compare-row > div {\n        padding: 16px 20px;\n    }\n\n    .compare-header {\n        display: none;\n    }\n\n\n\n    .compare-row > div:last-child {\n        border-bottom: 0;\n    }\n}\n\n\n\n.section-title .title {\n	font-weight: 800;\n	text-align: center;\n}\n.section-title .sub-title {\n	font-size: 11px;\n	font-weight: 700;\n	color: #00c4a0;\n	line-height: 17px;\n	text-align: center;\n	margin-block-end: 0px;\n}\n\n.card-box > .card {\n	border-radius: 32px;\n	border: 1px solid #F3F5F9;\n	background-color: #FFFFFF;\n}\n\n.card-hover-able:hover {\n    border-color: #00c4a073;\n    transform: translateY(-3px);\n    box-shadow: 0 12px 32px #00c4a01f;\n}\n\n.solution-section .e-svg-base {\n	background-color: #DCF7FD;\n	color: #4D658A;\n	border-radius: 50%;\n  padding: 8px;\n}\n', 'blocksy', '', 'inherit', 'closed', 'closed', '', '37-revision-v1', '', '', '2026-06-01 15:30:39', '2026-06-01 15:30:39', '', 37, 'http://laixeho.test/?p=1043', 0, 'revision', '', 0),
