direction: column;\n    gap: 12px;\n    z-index: 9999;\n}\n\n/* Base button */\n.phone-btn,\n.zalo-btn {\n    position: relative;\n    width: 52px;\n    height: 52px;\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    text-decoration: none;\n    overflow: visible;\n		color: #FFFFFF;\n}\n\n/* Icon */\n.phone-btn svg,\n.zalo-btn svg {\n    position: relative;\n    z-index: 2;\n    width: 22px;\n    height: 22px;\n}\n\n/* Pulse wrapper */\n.floating-effect {\n    position: absolute;\n    inset: 0;\n    border-radius: 50%;\n    z-index: 0;\n}\n\n/* Phone color */\n.phone-btn {\n    background: #00C4A0;\n}\n\n.phone-btn .floating-effect::before,\n.phone-btn .floating-effect::after {\n    content: \"\";\n    position: absolute;\n    inset: 0;\n    border-radius: 50%;\n    background: rgba(15, 23, 42, 0.4);\n    animation: pulse 2s infinite;\n}\n\n/* Zalo color */\n.zalo-btn {\n    background: #0084FF;\n}\n\n.zalo-btn .floating-effect::before,\n.zalo-btn .floating-effect::after {\n    content: \"\";\n    position: absolute;\n    inset: 0;\n    border-radius: 50%;\n    background: rgba(0, 104, 255, 0.4);\n    animation: pulse 1s infinite;\n}\n\n/* Delay để sóng đẹp hơn */\n.floating-effect::after {\n    animation-delay: 1s;\n}\n\n/* Pulse animation */\n@keyframes pulse {\n    0% {\n        transform: scale(1);\n        opacity: 0.6;\n    }\n    100% {\n        transform: scale(2);\n        opacity: 0;\n    }\n}', 'blocksy', '', 'inherit', 'closed', 'closed', '', '37-revision-v1', '', '', '2026-06-02 01:54:42', '2026-06-02 01:54:42', '', 37, 'http://laixeho.test/?p=1179', 0, 'revision', '', 0),
