ansition: background 0.2s ease;\\n}\\n\\n/* Mobile */\\n@media (max-width: 768px) {\\n    .price-grid {\\n        font-size: 14px;\\n    }\\n\\n    .price-grid .cell {\\n        padding: 10px 8px;\\n    }\\n}\\n\\n\\n.section-title .title {\\n\\tfont-weight: 800;\\n\\ttext-align: center;\\n}\\n.section-title .sub-title {\\n\\tfont-size: 11px;\\n\\tfont-weight: 700;\\n\\tcolor: #00c4a0;\\n\\tline-height: 17px;\\n\\ttext-align: center;\\n\\tmargin-block-end: 0px;\\n}\\n\\n.card-box > .card {\\n\\tborder-radius: 32px;\\n\\tborder: 1px solid #F3F5F9;\\n\\tbackground-color: #FFFFFF;\\n}\\n\\n.card-hover-able:hover {\\n    border-color: #00c4a073;\\n    transform: translateY(-3px);\\n    box-shadow: 0 12px 32px #00c4a01f;\\n}\\n\\n.solution-section .e-svg-base {\\n\\tbackground-color: #DCF7FD;\\n\\tcolor: #4D658A;\\n\\tborder-radius: 50%;\\n  padding: 8px;\\n}\\n\\n.reviews {\\n    display: grid;\\n    gap: 24px;\\n\\n    grid-template-columns:\\n        repeat(auto-fit, minmax(320px, 1fr));\\n\\n    grid-template-rows:\\n        auto\\n        1fr\\n        auto;\\n}\\n\\n.review-card {\\n    display: grid;\\n\\n    /* K\\u1ebf th\\u1eeba row t\\u1eeb grid cha */\\n    grid-template-rows: subgrid;\\n\\n    /* Chi\\u1ebfm 3 h\\u00e0ng c\\u1ee7a grid cha */\\n    grid-row: span 3;\\n\\n    padding: 24px;\\n    border-radius: 16px;\\n    border: 1px solid #ddd;\\n    background: white;\\n}\\n\\n.stars {\\n    font-size: 20px;\\n\\t\\tpadding-left: 0;\\n\\tgap: 2px;\\n}\\n\\n.stars .e-svg-base {\\n\\theight: 24px;\\n\\twidth: 24px;\\n}\\n\\n.content {\\n    margin: 0;\\n    line-height: 1.7;\\n}\\n\\n.author {\\n    display: flex !important;\\n    align-items: center;\\n    gap: 0;\\n    \\n\\t\\tpadding: 0;\\n}\\n\\n@media (max-width: 767px) {\\n    .author {\\n        flex-wrap: nowrap !important;\\n    }\\n}\\n\\n.review-avatar img {\\n    width: 60px;\\n    height: 60px;\\n    border-radius: 50%;\\n    object-fit: cover;\\n\\n    border: 3px solid #fff;\\n    box-shadow: