n}\\n\\n.author p:first-child {\\n    margin: 0;\\n    font-size: 1rem;\\n    font-weight: 700;\\n    color: #111827;\\n}\\n\\n.author p:last-child {\\n    margin: 2px 0 0;\\n    font-size: .875rem;\\n    color: #6b7280;\\n}\\n\\n.stars svg {\\n    width: 20px;\\n    height: 20px;\\n\\n    fill: #fbbf24;\\n    stroke: #fbbf24;\\n\\n    flex-shrink: 0;\\n}\\n\\n\\n.floating-btn-group {\\n    position: fixed;\\n    right: 20px;\\n    bottom: 72px;\\n    display: flex;\\n    flex-direction: column;\\n    gap: 12px;\\n    z-index: 9999;\\n}\\n\\n/* Base button */\\n.phone-btn,\\n.zalo-btn {\\n    position: relative;\\n    width: 52px;\\n    height: 52px;\\n    border-radius: 50%;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    text-decoration: none;\\n    overflow: visible;\\n\\t\\tcolor: #FFFFFF;\\n\\t\\ttransition: transform 0.2s ease; \\n}\\n\\n.phone-btn:hover,\\n.zalo-btn:hover {\\n\\tcolor: #FFFFFF;\\n\\ttransform: scale(1.2);\\n}\\n\\n/* Icon */\\n.phone-btn svg,\\n.zalo-btn svg {\\n    position: relative;\\n    z-index: 2;\\n    width: 22px;\\n    height: 22px;\\n}\\n\\n/* Pulse wrapper */\\n.floating-effect {\\n    position: absolute;\\n    inset: 0;\\n    border-radius: 50%;\\n    z-index: 0;\\n}\\n\\n/* Phone color */\\n.phone-btn {\\n    background: #00C4A0;\\n}\\n\\n.phone-btn .floating-effect::before,\\n.phone-btn .floating-effect::after {\\n    content: \\\"\\\";\\n    position: absolute;\\n    inset: 0;\\n    border-radius: 50%;\\n   background: rgba(0, 196, 160, 0.4);\\n    animation: pulse 1s infinite;\\n}\\n\\n/* Zalo color */\\n.zalo-btn {\\n    background: #0084FF;\\n}\\n\\n.zalo-btn .floating-effect::before,\\n.zalo-btn .floating-effect::after {\\n    content: \\\"\\\";\\n    position: absolute;\\n    inset: 0;\\n    border-radius: 50%;\\n    background: rgba(0, 104, 255, 0.4);\\n    animation: pulse 1s infinite;\\n}\\n\\n/* Delay \\u0111\\u1ec3 s\\u00f3ng \\u0111\\u1eb9p h\\u01a1n */\\n.floating-effect::after {