ansition: background 0.2s ease;\\n}\\n\\n/* Mobile */\\n@media (max-width: 768px) {\\n    .price-grid {\\n        font-size: 14px;\\n    }\\n\\n    .price-grid .cell {\\n        padding: 10px 8px;\\n    }\\n}\\n\\n\\n.section-title .title {\\n\\tfont-weight: 800;\\n\\ttext-align: center;\\n}\\n.section-title .sub-title {\\n\\tfont-size: 11px;\\n\\tfont-weight: 700;\\n\\tcolor: #00c4a0;\\n\\tline-height: 17px;\\n\\ttext-align: center;\\n\\tmargin-block-end: 0px;\\n}\\n\\n.card-box > .card {\\n\\tborder-radius: 32px;\\n\\tborder: 1px solid #F3F5F9;\\n\\tbackground-color: #FFFFFF;\\n}\\n\\n.card-hover-able:hover {\\n    border-color: #00c4a073;\\n    transform: translateY(-3px);\\n    box-shadow: 0 12px 32px #00c4a01f;\\n}\\n\\n.solution-section .e-svg-base {\\n\\tbackground-color: #DCF7FD;\\n\\tcolor: #4D658A;\\n\\tborder-radius: 50%;\\n  padding: 8px;\\n}\\n\\n.reviews {\\n    display: grid;\\n    gap: 24px;\\n\\n    grid-template-columns:\\n        repeat(auto-fit, minmax(320px, 1fr));\\n\\n    grid-template-rows:\\n        auto\\n        1fr\\n        auto;\\n}\\n\\n.review-card {\\n    display: grid;\\n\\n    /* K\\u1ebf th\\u1eeba row t\\u1eeb grid cha */\\n    grid-template-rows: subgrid;\\n\\n    /* Chi\\u1ebfm 3 h\\u00e0ng c\\u1ee7a grid cha */\\n    grid-row: span 3;\\n\\n    padding: 24px;\\n    border-radius: 16px;\\n    border: 1px solid #ddd;\\n    background: white;\\n}\\n\\n.stars {\\n    font-size: 20px;\\n\\t\\tpadding-left: 0;\\n\\tgap: 2px;\\n}\\n\\n.stars .e-svg-base {\\n\\theight: 24px;\\n\\twidth: 24px;\\n}\\n\\n.content {\\n    margin: 0;\\n    line-height: 1.7;\\n}\\n\\n.author * {\\n\\tbox-sizing: border-box;\\n}\\n\\n.author {\\n     display: grid;\\n    grid-template-columns: auto 1fr;\\n    align-items: center;\\n    gap: 8px;\\n\\tpadding: 0;\\n}\\n\\n\\n.review-avatar {\\n\\t width: 42px;\\n    height: 42px;\\n\\timg {\\n\\t\\twidth: 100% !important;\\n\\t\\theight: 100% !important;\\n\\t}\\n}\\n\\n.author div:first-child {\\n\\tpadding: 0;\\n}\\n.author div:last-child {\\n\\tgap: 0;\\n}\\n\\n.author p:first-child {\\n    margin: 0;\\n    font-size: 1rem;\\n    font-weight: 700;\\n    color: #111827;\\n}\\n\\n.author p:last-child {\\n    margin: 2px 0 0;\\n    font-size: .875rem;\\n    color: #6b7280;\\n}\\n\\n.stars svg {\\n    width: 20px;\\n    height: 20px;\\n\\n    fill: #fbbf24;\\n    stroke: #fbbf24;\\n\\n    flex-shrink: 0;\\n}\\n\\n\\n.floating-btn-group {\\n    position: fixed;\\n    right: 20px;\\n    bottom: 72px;\\n    display: flex;\\n    flex-direction: column;\\n    gap: 12px;\\n    z-index: 9999;\\n}\\n\\n/* Base button */\\n.phone-btn,\\n.zalo-btn {\\n    position: relative;\\n    width: 52px;\\n    height: 52px;\\n    border-radius: 50%;\\n    display: flex;\\n    align-items: center;\\n    justify-content: center;\\n    text-decoration: none;\\n    overflow: visible;\\n\\t\\tcolor: #FFFFFF;\\n\\t\\ttransition: transform 0.2s ease; \\n}\\n\\n.phone-btn:hover,\\n.zalo-btn:hover {\\n\\tcolor: #FFFFFF;\\n\\ttransform: scale(1.2);\\n}\\n\\n/* Icon */\\n.phone-btn svg,\\n.zalo-btn svg {\\n    position: relative;\\n    z-index: 2;\\n    width: 22px;\\n    height: 22px;\\n}\\n\\n/* Pulse wrapper */\\n.floating-effect {\\n    position: absolute;\\n    inset: 0;\\n    border-radius: 50%;\\n    z-index: 0;\\n}\\n\\n/* Phone color */\\n.phone-btn {\\n    background: #00C4A0;\\n}\\n\\n.phone-btn .floating-effect::before,\\n.phone-btn .floating-effect::after {\\n    content: \\\"\\\";\\n    position: absolute;\\n    inset: 0;\\n    border-radius: 50%;\\n   background: rgba(0, 196, 160, 0.4);\\n    animation: pulse 1s infinite;\\n}\\n\\n/* Zalo color */\\n.zalo-btn {\\n    background: #0084FF;\\n}\\n\\n.zalo-btn .floating-effect::before,\\n.zalo-btn .floating-effect::after {\\n    content: \\\"\\\";\\n    position: absolute;\\n    inset: 0;\\n    border-radius: 50%;\\n    background: rgba(0, 104, 255, 0.4);\\n    animation: pulse 1s infinite;\\n}\\n\\n/* Delay \\u0111\\u1ec3 s\\u00f3ng \\u0111\