r-radius: 32px;\n}\n.working-group {	\n	display: grid;\n	grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\n	gap: 24px;\n	\n	.working-step {\n		position: relative;\n		border: 1px solid var(--card-border-strong);\n		background-color: #FFFFFF;\n		border-radius: 32px;\n		padding: 24px;\n		.icon {\n			width: 42px;\n			height: 42px;\n			color: #FFFFFF;\n			margin-bottom: 24px;\n			border-radius: 50%;\n			display: flex;\n			justify-content: center;\n			align-items: center;\n			background-image: linear-gradient(\n    to bottom right in oklab,\n    #00c4a0 0%,\n    #00cfee 50%,\n    #4f6ef7 100%\n);\n		}\n	}\n}\n\n.working-step:not(:last-child)::after {\n    content: \"\\2794\";\n    position: absolute;\n    right: -25px;\n    top: 50%;\n    width: 20px;\n    height: 20px;\n    background: url(\"data:image/svg+xml,%3Csvg viewBox=\'0 0 24 24\' fill=\'none\' stroke=\'%23999\'%3E%3Cpath d=\'M5 12h14m0 0l-6-6m6 6l-6 6\'/%3E%3C/svg%3E\");\n    background-size: contain;\n    background-repeat: no-repeat;\n}\n\n\n\n.floating-btn-group {\n    position: fixed;\n    right: 20px;\n    bottom: 72px;\n    display: flex;\n    flex-direction: column;\n    gap: 12px;\n    z-index: 9999;\n}\n\n/* Base button */\n.phone-btn,\n.zalo-btn {\n    position: relative;\n    width: 52px;\n    height: 52px;\n    border-radius: 50%;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    text-decoration: none;\n    overflow: visible;\n		color: #FFFFFF;\n		transition: transform 0.2s ease; \n}\n\n.phone-btn:hover,\n.zalo-btn:hover {\n	color: #FFFFFF;\n	transform: scale(1.2);\n}\n\n/* Icon */\n.phone-btn svg,\n.zalo-btn svg {\n    position: relative;\n    z-index: 2;\n    width: 22px;\n    height: 22px;\n}\n\n/* Pulse wrapper */\n.floating-effect {\n    position: absolute;\n    inset: 0;\n    border-radius: 50%;\n    z-index: 0;\n}\n\n/* Phone color */\n.phone-btn {\n    background: #00C4A0;\n}\n\n.phone-btn .floating-effect::before,\n.phone-btn .floating-effect::after